const SCHEMA_VERSION = '1.0';
const MAX_MESSAGE_LENGTH = 4000;
const SYNTHETIC_ID = /^SYN-[A-Z0-9][A-Z0-9-]{2,39}$/;
const URL_PATTERN = /https?:\/\/|www\./i;

const CATEGORY_RULES = [
  ['access_issue', ['cannot log in', "can't log in", 'locked out', 'sign in', 'login']],
  ['billing', ['charged', 'charge', 'billing', 'invoice', 'refund', 'payment']],
  ['service_disruption', ['service unavailable', 'unavailable', 'outage', 'not working', 'system down', 'stopped working']],
  ['account_change', ['change account', 'update profile', 'change name', 'account update']],
];

const PROMPT_INJECTION_TERMS = [
  'ignore previous instructions',
  'ignore all instructions',
  'reveal system prompt',
  'show system prompt',
  'bypass safety',
  'disable human review',
  'human_review_required false',
  'human_review_required\": false',
];

const containsAny = (text, terms) => terms.some((term) => text.includes(term));

function validateInput(value) {
  if (value === null || Array.isArray(value) || typeof value !== 'object') {
    return ['input must be a JSON object'];
  }

  const errors = [];
  const allowedKeys = new Set(['request_id', 'message']);
  const extraKeys = Object.keys(value).filter((key) => !allowedKeys.has(key)).sort();
  if (extraKeys.length) {
    errors.push(`unexpected fields: ${extraKeys.join(', ')}`);
  }

  if (typeof value.request_id !== 'string' || !SYNTHETIC_ID.test(value.request_id)) {
    errors.push('request_id must match SYN-[A-Z0-9-] and be 7-44 characters long');
  }

  if (typeof value.message !== 'string') {
    errors.push('message must be a string');
  } else if (!value.message.trim()) {
    errors.push('message must not be empty');
  } else if ([...value.message].length > MAX_MESSAGE_LENGTH) {
    errors.push(`message must be at most ${MAX_MESSAGE_LENGTH} characters`);
  }

  return errors;
}

function securityFlags(text) {
  const flags = [];
  if (containsAny(text, PROMPT_INJECTION_TERMS)) flags.push('prompt_injection');
  if (containsAny(text, ['password', 'passcode', 'api key', 'access token', 'secret token'])) flags.push('credential_request');
  if (containsAny(text, ['card number', 'credit card', 'security code', 'cvv'])) flags.push('payment_data');
  if (containsAny(text, ['passport number', 'national id', 'identity document'])) flags.push('sensitive_identity_data');
  if (URL_PATTERN.test(text)) flags.push('suspicious_link');
  return flags.sort();
}

function classifyCategory(text) {
  for (const [category, terms] of CATEGORY_RULES) {
    if (containsAny(text, terms)) return category;
  }
  return 'general';
}

function classifyUrgency(text, flags) {
  if (containsAny(text, ['immediate danger', 'medical emergency', 'safety emergency'])) return 'critical';
  if (containsAny(text, ['urgent', 'stranded', 'locked out', 'system down', 'cannot access', "can't access"])) return 'high';
  if (flags.length) return 'high';
  if (containsAny(text, ['when convenient', 'no rush', 'general question'])) return 'low';
  return 'normal';
}

function missingInformation(category, text) {
  const missing = [];
  if (category === 'access_issue') {
    if (!containsAny(text, ['account', 'profile', 'workspace'])) missing.push('affected account context');
    if (!containsAny(text, ['browser', 'device', 'app', 'desktop', 'mobile'])) missing.push('device or application context');
  } else if (category === 'billing') {
    if (!containsAny(text, ['invoice', 'transaction', 'order', 'receipt', 'synthetic reference'])) missing.push('synthetic transaction reference');
    if (!containsAny(text, ['date', 'today', 'yesterday'])) missing.push('approximate event date');
  } else if (category === 'service_disruption') {
    if (!containsAny(text, ['dashboard', 'portal', 'service', 'app', 'feature'])) missing.push('affected service or feature');
    if (!containsAny(text, ['since', 'started', 'today', 'minute', 'hour'])) missing.push('time the issue began');
  } else if (category === 'account_change') {
    if (!containsAny(text, ['name', 'setting', 'preference', 'profile'])) missing.push('account field to change');
  } else if (text.split(/\s+/).filter(Boolean).length < 8 || containsAny(text, ['help me', 'it failed', 'problem'])) {
    missing.push('specific issue and desired outcome');
  }
  return missing;
}

function rationale(category, urgency, flags) {
  const categoryReasons = {
    access_issue: 'The request describes a sign-in or access problem.',
    account_change: 'The request asks for an account or profile change.',
    billing: 'The request concerns a charge, payment, invoice, or refund.',
    service_disruption: 'The request describes unavailable or failing service.',
    general: 'The request lacks a more specific supported category.',
  };
  const urgencyReasons = {
    low: 'It explicitly indicates that no prompt response is needed.',
    normal: 'No deterministic high-urgency indicator was found.',
    high: 'Urgent access, disruption, or security-review indicators were found.',
    critical: 'The text contains an explicit safety or medical emergency indicator.',
  };
  const securityReason = flags.length ? ' Security-sensitive content requires review.' : '';
  return `${categoryReasons[category]} ${urgencyReasons[urgency]}${securityReason}`;
}

function suggestedReply(category, missing, flags) {
  const opening = flags.length
    ? 'Draft for human review: We received your request, but it contains content that requires a security review.'
    : `Draft for human review: We received your ${category.replaceAll('_', ' ')} request.`;
  if (missing.length) {
    return `${opening} Please provide: ${missing.join(', ')}. Do not include passwords, payment-card data, or identity documents.`;
  }
  return `${opening} A support operator will review the details before any action is taken.`;
}

function rejectedResult(value, errors) {
  const requestId = value !== null && !Array.isArray(value) && typeof value === 'object'
    && typeof value.request_id === 'string' && SYNTHETIC_ID.test(value.request_id)
    ? value.request_id
    : null;
  return {
    schema_version: SCHEMA_VERSION,
    status: 'rejected',
    request_id: requestId,
    category: 'unknown',
    urgency: 'unknown',
    rationale: 'Input validation failed; no classification was attempted.',
    missing_information: [],
    suggested_reply: 'Draft for human review: The request could not be processed safely. Please provide a valid synthetic request.',
    security_flags: ['invalid_input'],
    human_review_required: true,
    errors,
  };
}

const input = $input.first().json;
const errors = validateInput(input);
if (errors.length) {
  return [{ json: rejectedResult(input, errors) }];
}

const text = input.message.trim().toLowerCase();
const flags = securityFlags(text);
const category = classifyCategory(text);
const urgency = classifyUrgency(text, flags);
const missing = missingInformation(category, text);

return [{
  json: {
    schema_version: SCHEMA_VERSION,
    status: 'accepted',
    request_id: input.request_id,
    category,
    urgency,
    rationale: rationale(category, urgency, flags),
    missing_information: missing,
    suggested_reply: suggestedReply(category, missing, flags),
    security_flags: flags,
    human_review_required: true,
    errors: [],
  },
}];

const REQUIRED_FIELDS = [
  'category',
  'errors',
  'human_review_required',
  'missing_information',
  'rationale',
  'request_id',
  'schema_version',
  'security_flags',
  'status',
  'suggested_reply',
  'urgency',
];
const CATEGORIES = new Set(['access_issue', 'account_change', 'billing', 'service_disruption', 'general', 'unknown']);
const URGENCIES = new Set(['low', 'normal', 'high', 'critical', 'unknown']);
const STATUSES = new Set(['accepted', 'rejected']);
const SECURITY_FLAGS = new Set(['credential_request', 'invalid_input', 'payment_data', 'prompt_injection', 'sensitive_identity_data', 'suspicious_link']);
const SYNTHETIC_ID = /^SYN-[A-Z0-9][A-Z0-9-]{2,39}$/;

function fallback() {
  return {
    schema_version: '1.0',
    status: 'rejected',
    request_id: null,
    category: 'unknown',
    urgency: 'unknown',
    rationale: 'Output validation failed; no workflow action was attempted.',
    missing_information: [],
    suggested_reply: 'Draft for human review: The request could not be processed safely. Please review the workflow result.',
    security_flags: ['invalid_input'],
    human_review_required: true,
    errors: ['output validation failed'],
  };
}

function isStringArray(value) {
  return Array.isArray(value) && value.every((item) => typeof item === 'string');
}

function isValid(value) {
  if (value === null || Array.isArray(value) || typeof value !== 'object') return false;
  const fields = Object.keys(value).sort();
  if (JSON.stringify(fields) !== JSON.stringify(REQUIRED_FIELDS)) return false;
  if (value.schema_version !== '1.0') return false;
  if (typeof value.status !== 'string' || !STATUSES.has(value.status)) return false;
  if (typeof value.category !== 'string' || !CATEGORIES.has(value.category)) return false;
  if (typeof value.urgency !== 'string' || !URGENCIES.has(value.urgency)) return false;
  if (value.human_review_required !== true) return false;
  if (value.request_id !== null && (typeof value.request_id !== 'string' || !SYNTHETIC_ID.test(value.request_id))) return false;
  if (typeof value.rationale !== 'string' || !value.rationale) return false;
  if (typeof value.suggested_reply !== 'string' || !value.suggested_reply.startsWith('Draft for human review:')) return false;
  if (!isStringArray(value.missing_information) || !isStringArray(value.security_flags) || !isStringArray(value.errors)) return false;
  if (!value.security_flags.every((flag) => SECURITY_FLAGS.has(flag))) return false;
  if (value.status === 'accepted' && value.errors.length) return false;
  if (value.status === 'rejected' && (!value.errors.length || !value.security_flags.includes('invalid_input'))) return false;
  return true;
}

const items = $input.all();
const candidate = items.length === 1 ? items[0].json : null;
const guarded = isValid(candidate) ? candidate : fallback();
guarded.human_review_required = true;
return [{ json: guarded }];
